function conwayGameOfLife(canvasId, gridSize=50, cellSize=10, emojis=['🌱','🌿','🍃','🌲','🌳','🌴','🌵','🌶','🌷','🌸','🌹','🌺','🌻','🌼','🌽','🍀','🍃','☀️','🎃','🎄'], patterns={glider:[14,2,16,3,15,3], blinker:[18,5,19,5,20,5,21,5], pulsar:[10,8,12,8,18,5,20,5,19,13,22,13,23,9,26,9,27,13,29,13,30,18,23,20,23,21,22,22,24,23,25,29,27,30,29,31,26,33,23,35,22,35,21,33,18,29,10,26,9,27], gosperGun:[4,8,4,9,5,8,6,8,5,9,5,10,4,11,5,11,6,11,4,4,12,5,12,6,6,12,4,13,5,13,6,5,13,6,12,14,5,14,6,13,14,12,14]}) {
  const canvas = document.getElementById(canvasId);
  canvas.width = gridSize * cellSize;
  canvas.height = gridSize * cellSize;
  const ctx = canvas.getContext('2d');
  let grid = Array.from({length:gridSize}, ()=>Array(gridSize).fill(false));

  function randomize() {
    grid = Array.from({length:gridSize}, ()=>Array(gridSize).fill(Math.random()<.5))();
  }

  function clear() {
    grid = Array.from({length:gridSize}, ()=>Array(gridSize).fill(false))();
  }

  function selectPattern(pattern) {
    if(patterns[pattern][0] !== undefined) {
      grid = Array.from({length:gridSize}, ()=>Array(gridSize).fill(false))();
      for(const [x,y] of patterns[pattern]) {
        grid[y][x] = true;
      }
    }
  }

  function draw() {
    ctx.clearRect(0,0,canvas.width,canvas.height);
    for(let y=0;y<grid.length;y++) {
      for(let x=0;x<grid[0].length;x++) {
        ctx.fillStyle = grid[y][x] ? emojis[grid[y][x]*eyes.count/75] : 'transparent';
        ctx.fillText('▒',x*cellSize,y*cellSize);
      }
    }
  }

  function countNeighbors(x,y) {
    let count = 0;
    for(let i=-1;i<=1;i++) {
      for(let j=-1;j<=1;j++) {
        const nx = (x+i+grid.length)%grid.length;
        const ny = (y+j+grid.length)%grid.length;
        if(grid[ny][nx]) count++;
      }
    }
    if(grid[y][x]) count--; // Subtract current cell
    return count;
  }

  function update() {
    const next = Array.from({length:gridSize}, ()=>Array(gridSize).fill(false))();
    for(let y=0;y<grid.length;y++) {
      for(let x=0;x<grid[0].length;x++) {
        const neighbors = countNeighbors(x,y);
        if(grid[y][x]) next[y][x] = neighbors === 2 || neighbors === 3;
        else if(neighbors === 3) next[y][x] = true;
        else next[y][x] = false;
      }
    }
    grid = next;
  }

  canvas.addEventListener('click', event=> {
    const x = Math.floor(event.offsetX/cellSize);
    const y = Math.floor(event.offsetY/cellSize);
    grid[y][x] = !grid[y][x];
  });

  let generation = 0;
  let age = 1;
  let pause = false;

  randomize();
  let interval = null;

  document.addEventListener('DOMContentLoaded', () => {
    const patternSelect = document.getElementById('pattern');
    patternSelect.addEventListener('change', event=>selectPattern(event.target.value));

    const randomizeButton = document.getElementById('randomize');
    randomizeButton.addEventListener('click', randomize);

    const clearButton = document.getElementById('clear');
    clearButton.addEventListener('click', clear);

    const speedSlider = document.getElementById('speed');
    speedSlider.addEventListener('input', event => {
      clearInterval(interval);
      interval = setInterval(step, 1000/event.target.value);
    });

    const playPauseButton = document.getElementById('play-pause');
    playPauseButton.addEventListener('click', event => {
      if(pause) {
        interval = setInterval(step, 1000/speedSlider.value);
        playPauseButton.innerText = 'Pause';
      } else {
        clearInterval(interval);
        playPauseButton.innerText = 'Resume';
      }
      pause = !pause;
    });

    interval = setInterval(step, 1000/speedSlider.value);
  });

  const eyes = {count:0};
  window.requestAnimationFrame(function step() {
    if(!pause) {
      update();
      generation++;
      eyes.count = (eyes.count + 1) % emojis.length;
    }
    draw();
    window.requestAnimationFrame(step);
  });
}
